def locate(cls,method):
 paths=list((REPO/'src/main/java').rglob(cls+'.java'))
 if not paths:return cls+'.'+method+' [unresolved]'
 path=paths[0];s=path.read_text(encoding='utf8');m=re.search(r'\b'+re.escape(method)+r'\s*\(',s)
 return str(path.relative_to(REPO)).replace('\\','/')+(':'+str(s[:m.start()].count('\n')+1) if m else '')+' :: '+method+'()'

