table(p,'SQLite tables and integrity rules',['Table','Important data and constraints'],[['users','id PK; username UNIQUE; password_hash; recommendations_enabled; created_at.'],['categories','id PK; nullable user_id FK for system categories; name; INCOME/EXPENSE; is_system.'],['transactions','id PK; user/category FKs; positive amount_paise; type; txn_date; payment_mode; notes; optional recurring_rule_id; created_at.'],['budgets','id PK; user/category FKs; year_month; positive limit_paise; UNIQUE(user,category,month).'],['savings_goals','id PK; user FK; title; positive target_paise; nonnegative saved_paise; deadline; ratio 0-100; is_active.'],['recurring_rules','id PK; user/category FKs; amount_paise; type; frequency; start_date; next_due_date; end_date; status.'],['execution_audit_log','id PK; rule_id FK; run_at; result; message.'],['user_fixed_categories','Composite PK(user_id,category_id); both foreign keys.'],['user_fixed_category_initializations','user_id PK/FK; records completed default-preference initialization.']],[.31,.69])
text(p,'DatabaseManager enables PRAGMA foreign_keys on each connection. Transaction dates and year-month values are stored as text and selected using an ISO month prefix. User-related rows generally cascade when a user is deleted at DAO level, although the UI does not offer account deletion. Deleting a recurring rule sets existing transaction recurring_rule_id values to NULL and cascades its execution audit rows.',
'The relational references support one user to many transactions, budgets and goals, and one category to many transactions. A system category may have no owning user. Java domain objects store foreign-key identifiers rather than direct nested User/Category object references. The schema does not encode the cross-row active-ratio total; GoalService enforces it in application logic.')
