def save_content():
 source_files=list((REPO/'src').rglob('*'))+[REPO/'pom.xml']+list((REPO/'data').glob('*.db'))
 manifest={str(p.relative_to(REPO)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in source_files if p.is_file()}
 (ROOT/'evidence/source_manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf8')
 index={}
 for path in (REPO/'src/main/java').rglob('*.java'):
  s=path.read_text(encoding='utf8');methods=[]
  for m in re.finditer(r'^\s*(?:public|protected|private)\s+(?:(?:static|final|synchronized|abstract)\s+)*(?:[\w<>?,.\[\] ]+\s+)?(\w+)\s*\(',s,re.M):methods.append({'method':m.group(1),'line':s[:m.start()].count('\n')+1})
  index[str(path.relative_to(REPO)).replace('\\','/')]=methods
 (ROOT/'evidence/source_index.json').write_text(json.dumps(index,indent=2),encoding='utf8')
 (ROOT/'report_content.json').write_text(json.dumps(pages,ensure_ascii=False,indent=2),encoding='utf8')
 md=['# Requirements traceability','', 'Baseline: original FR-01 through FR-08 from MST slide 5. EXT IDs identify final-scope additions. Status refers to implementation inspection; executed evidence is separately labeled.','', '| Feature | Requirement | Use case | Java methods and locations | Tables | Screen | Status | Tests |','|---|---|---|---|---|---|---|---|']
 for feature,cls,methods,db,screen,status,req,u,t in features:
  refs='<br>'.join(locate(cls,m) for m in methods.split(','));md.append(f'| {feature} | {req} | {u} | {refs} | {db} | {screen} | {status} | {t} |')
 md+=['','## Automated case mapping','']+[f'- {id}: `{cls}.{meth}()` — {expect}.' for id,cls,meth,expect in AUTOS]
 md+=['','## Planned manual case mapping','']+[f'- {id} ({req}, {u}): {inp} Expected: {exp} Actual: not available. Status: Not Executed.' for id,req,inp,exp,u in MANUAL]
 md+=['','## MST and source-comment crosswalk','','- FR-01 retains authentication.','- MST FR-02/03 encompass code transaction comments FR-02..05.','- MST FR-04 budgets correspond to code FR-06/07.','- MST FR-05 goals correspond to code FR-08/09.','- MST FR-06 recurring retains its functional meaning, irrespective of comment aliases.','- MST FR-07 preview retains its functional meaning.','- MST FR-08 advice/reports correspond to code FR-13/14.','- EXT-01 dashboard corresponds to code FR-15.','- EXT-03 fixed categories corresponds to code FR-16.','- React, Spring, Hibernate, REST, MySQL/PostgreSQL and browser/cloud assumptions are not implemented.','- MST sprint/interview claims are historical proposals; no evidence of actual ceremonies or user studies supplied.']
 (ROOT/'REQUIREMENTS_TRACEABILITY.md').write_text('\n'.join(md),encoding='utf8')
 return pages
